index 479a3ca..84cedd7 100644
--- a/crates/ocean-agent/src/session/mod.rs
+++ b/crates/ocean-agent/src/session/mod.rs
@@ -507,6 +507,275 @@ pub fn detail(config_dir: &Path, id: SessionId) -> anyhow::Result<SessionDetail>
     Ok(session_detail(session))
