   14	/// A typeahead client can supersede a request before its blocking filesystem
   15	/// scan notices. Bound concurrent scans globally so abandoned/parallel queries
   16	/// cannot flood Tokio's blocking pool or multiply full-store I/O without limit.
   17	const MAX_CONCURRENT_HISTORY_SEARCHES: usize = 2;
   18	static HISTORY_SEARCH_SLOTS: LazyLock<Arc<Semaphore>> =
   19	    LazyLock::new(|| Arc::new(Semaphore::new(MAX_CONCURRENT_HISTORY_SEARCHES)));
