  510	/// Search persisted display transcript text for user and assistant entries only.
  511	/// Tool results and non-display content blocks are never considered.
  512	pub fn search_history(
  513	    config_dir: &Path,
  514	    query: &str,
  515	    limit: usize,
  516	) -> anyhow::Result<Vec<HistorySearchHit>> {
  517	    let root = sessions_dir(config_dir);
  518	    if !root.exists() {
  519	        return Ok(Vec::new());
  520	    }
  521	
  522	    let mut paths = Vec::new();
  523	    for entry in std::fs::read_dir(&root)
  524	        .with_context(|| format!("read {}", root.display()))?
  525	        .flatten()
  526	    {
  527	        let path = entry.path();
  528	        if path.is_dir() {
  529	            if let Ok(children) = std::fs::read_dir(&path) {
  530	                paths.extend(children.flatten().map(|child| child.path()));
  531	            }
  532	        } else {
  533	            paths.push(path);
  534	        }
  535	    }
  536	    paths.retain(|path| path.extension().and_then(|value| value.to_str()) == Some("json"));
  537	    paths.sort();
  538	
  539	    // Preserve the one-id-one-session invariant even if a stale duplicate is
  540	    // present on disk. Selection mirrors the resumable loader, without mutating
  541	    // files on this read-only path.
  542	    let mut sessions: HashMap<SessionId, (PathBuf, Session)> = HashMap::new();
  543	    for path in paths {
  544	        let Ok(text) = std::fs::read_to_string(&path) else {
  545	            continue;
  546	        };
  547	        let Ok(candidate) = serde_json::from_str::<Session>(&text) else {
  548	            continue;
  549	        };
  550	        let replace = sessions
  551	            .get(&candidate.id)
  552	            .is_none_or(|(winner_path, winner)| {
  553	                candidate.updated_ms > winner.updated_ms
  554	                    || (candidate.updated_ms == winner.updated_ms
  555	                        && (candidate.messages.len() > winner.messages.len()
  556	                            || (candidate.messages.len() == winner.messages.len()
  557	                                && path > *winner_path)))
  558	            });
  559	        if replace {
  560	            sessions.insert(candidate.id, (path, candidate));
  561	        }
  562	    }
  563	
  564	    let mut hits = Vec::new();
  565	    for (_, session) in sessions.into_values() {
  566	        let title = first_user_text(&session.messages);
  567	        for (message_index, message) in session.messages.iter().enumerate() {
  568	            let entry = transcript_entry(message);
  569	            if !matches!(entry.role.as_str(), "user" | "assistant") || entry.text.trim().is_empty()
  570	            {
  571	                continue;
  572	            }
  573	            let squashed = entry.text.split_whitespace().collect::<Vec<_>>().join(" ");
  574	            let Some((match_kind, score, match_span)) = score_match(query, &squashed) else {
  575	                continue;
  576	            };
  577	            hits.push(HistorySearchHit {
  578	                hit_id: format!("{}:{message_index}", session.id),
  579	                session_id: session.id,
  580	                session_title: title.clone(),
  581	                role: entry.role,
  582	                excerpt: bounded_excerpt(&squashed, match_span),
  583	                timestamp_ms: entry.timestamp_ms,
  584	                workspace_root: session.workspace_root.clone(),
  585	                score,
  586	                match_kind,
  587	            });
  588	            // Keep memory proportional to the requested result bound rather
  589	            // than the number of matching turns in the complete session store.
  590	            let prune_at = limit.saturating_mul(4).max(limit.saturating_add(1));
  591	            if hits.len() >= prune_at {
  592	                hits.sort_by(compare_history_hits);
  593	                hits.truncate(limit.saturating_mul(2).max(limit));
  594	            }
  595	        }
  596	    }
  597	
  598	    hits.sort_by(compare_history_hits);
  599	    hits.truncate(limit);
  600	    Ok(hits)
  601	}
