  603	fn compare_history_hits(a: &HistorySearchHit, b: &HistorySearchHit) -> std::cmp::Ordering {
  604	    match_rank(b.match_kind)
  605	        .cmp(&match_rank(a.match_kind))
  606	        .then_with(|| b.score.total_cmp(&a.score))
  607	        .then_with(|| {
  608	            b.timestamp_ms
  609	                .unwrap_or(0)
  610	                .cmp(&a.timestamp_ms.unwrap_or(0))
  611	        })
  612	        .then_with(|| a.hit_id.cmp(&b.hit_id))
  613	}
