   14	/// A typeahead client can supersede a request before its blocking filesystem
   15	/// scan notices. Bound concurrent scans globally so abandoned/parallel queries
   16	/// cannot flood Tokio's blocking pool or multiply full-store I/O without limit.
   17	const MAX_CONCURRENT_HISTORY_SEARCHES: usize = 2;
   18	static HISTORY_SEARCH_SLOTS: LazyLock<Arc<Semaphore>> =
   19	    LazyLock::new(|| Arc::new(Semaphore::new(MAX_CONCURRENT_HISTORY_SEARCHES)));
   20	
   21	#[derive(Debug, Default, Deserialize)]
   22	pub(super) struct HistorySearchQuery {
   23	    #[serde(default)]
   24	    q: Option<String>,
   25	    #[serde(default)]
   26	    limit: Option<usize>,
   27	}
   28	
   29	#[derive(Debug, Serialize)]
   30	pub(super) struct HistorySearchResponse {
   31	    ok: bool,
   32	    query: String,
   33	    hits: Vec<HistorySearchHit>,
   34	    error: Option<String>,
   35	}
   36	
   37	/// `GET /v1/agent/history/search` searches only ocean-agent's persisted,
   38	/// display-ready transcript projection. The blocking file scan runs off the
   39	/// async executor and cannot invoke a provider or embedding service.
   40	pub(super) async fn history_search(
   41	    State(state): State<AppState>,
   42	    Query(params): Query<HistorySearchQuery>,
   43	) -> (StatusCode, Json<HistorySearchResponse>) {
   44	    let query = params.q.unwrap_or_default();
   45	    if query.trim().is_empty() {
   46	        return response(
   47	            StatusCode::BAD_REQUEST,
   48	            query,
   49	            Vec::new(),
   50	            Some("query parameter q must not be empty".into()),
   51	        );
   52	    }
   53	    if query.trim().chars().count() > MAX_HISTORY_SEARCH_QUERY_CHARS {
   54	        return response(
   55	            StatusCode::BAD_REQUEST,
   56	            query,
   57	            Vec::new(),
   58	            Some(format!(
   59	                "query exceeds {MAX_HISTORY_SEARCH_QUERY_CHARS} characters"
   60	            )),
   61	        );
   62	    }
   63	    let permit = match HISTORY_SEARCH_SLOTS.clone().try_acquire_owned() {
   64	        Ok(permit) => permit,
   65	        Err(_) => {
   66	            return response(
   67	                StatusCode::TOO_MANY_REQUESTS,
   68	                query,
   69	                Vec::new(),
   70	                Some("too many transcript history searches are already running".into()),
   71	            );
   72	        }
   73	    };
   74	
   75	    let runtime: Arc<AgentRuntime> = state.runtime.clone();
   76	    let search_query = query.clone();
   77	    match tokio::task::spawn_blocking(move || {
   78	        let _permit = permit;
   79	        runtime.search_history(&search_query, params.limit)
   80	    })
   81	    .await
   82	    {
   83	        Ok(Ok(hits)) => response(StatusCode::OK, query, hits, None),
   84	        Ok(Err(error)) => {
   85	            tracing::warn!(error = %error, "history transcript search failed");
   86	            response(
   87	                StatusCode::INTERNAL_SERVER_ERROR,
   88	                query,
   89	                Vec::new(),
   90	                Some("transcript history could not be searched".into()),
   91	            )
   92	        }
   93	        Err(error) => {
   94	            tracing::warn!(error = %error, "history transcript search task failed");
   95	            response(
   96	                StatusCode::INTERNAL_SERVER_ERROR,
   97	                query,
   98	                Vec::new(),
   99	                Some("transcript history could not be searched".into()),
  100	            )
  101	        }
  102	    }
  103	}
