  109	    error: Option<String>,
  110	) -> (StatusCode, Json<HistorySearchResponse>) {
  111	    (
  112	        status,
  113	        Json(HistorySearchResponse {
  114	            ok: status.is_success(),
  115	            query,
  116	            hits,
  117	            error,
  118	        }),
  119	    )
  120	}
18535	        );
18536	    }
